            mid = (lo + hi) >> 1
            if key < keys[mid][0]:
                hi = mid
            else:
                lo = mid + 1
        idx = lo
        total = sum(lens[:idx])
        if idx < len(keys):
            seg = keys[idx]
            p = _bisect_left(seg, key)
            q = p
            n = len(seg)
            while q < n and not (key < seg[q]):
                q += 1
            total += q
