"""Rank policies.

Every policy assigns an exact integer rank on every enqueue attempt (rejected
attempts advance FIFO/WFQ rank state too), consumes service feedback through
``post_dequeue`` and can snapshot/restore its complete state so save/restore
branches stay isolated.  Certificates use the shapes required by PROTOCOL.md.
"""
from packet import Pkt

QUANTUM = 1048576


class SchedulingAlgorithm:
    """Rank policy interface."""

    kind = 'base'

    def __init__(self, *args, **kwargs):
        pass

    def rank_cal(self, pkt: Pkt) -> int:
        raise NotImplementedError("Subclasses should implement this method.")

    def post_dequeue(self, pkt: Pkt, rank: int):
        """Service feedback; only a successful pop reaches this hook."""

    def set_weight(self, flow, weight):
        raise ValueError('weight reconfiguration unsupported by this policy')

    def snapshot(self):
        raise NotImplementedError

    def restore(self, state):
        raise NotImplementedError

    def certificate(self):
        raise NotImplementedError


class FifoAlgorithm(SchedulingAlgorithm):
    """Ranks are successive values of a policy counter starting at zero."""

    kind = 'fifo'
    __slots__ = ('time',)

    def __init__(self, time=0):
        self.time = time

    def rank_cal(self, pkt: Pkt) -> int:
        self.time += 1
        return self.time

    def snapshot(self):
        return ('fifo', self.time)

    def restore(self, state):
        self.time = state[1]

    def certificate(self):
        return {'kind': 'fifo', 'time': self.time}


class SpAlgorithm(SchedulingAlgorithm):
    """Strict priority: the configured level of the packet's flow."""

    kind = 'sp'
    __slots__ = ('flowid2pri',)

    def __init__(self, flowid2pri):
        self.flowid2pri = dict(flowid2pri)

    def rank_cal(self, pkt: Pkt) -> int:
        try:
            return self.flowid2pri[pkt.flowid]
        except KeyError:
            raise ValueError('undeclared strict-priority flow') from None

    def snapshot(self):
        return ('sp', dict(self.flowid2pri))

    def restore(self, state):
        self.flowid2pri = dict(state[1])

    def certificate(self):
        return {'kind': 'sp',
                'levels': [[flow, self.flowid2pri[flow]]
                           for flow in sorted(self.flowid2pri)]}


class pFabricAlgorithm(SchedulingAlgorithm):
    """Shortest-flow-first: the supplied packet flow_size is the rank."""

    kind = 'sff'
    __slots__ = ()

    def __init__(self):
        pass

    def rank_cal(self, pkt: Pkt) -> int:
        return pkt.flow_size

    def snapshot(self):
        return ('sff',)

    def restore(self, state):
        pass

    def certificate(self):
        return {'kind': 'sff'}


# Alias used by the experiment adapter.
SffAlgorithm = pFabricAlgorithm


class WFQAlgorithm(SchedulingAlgorithm):
    """Quantized weighted fair queueing finish tags, exact integer arithmetic.

    ``F[flow] = max(F[flow], V) + ceil(length * 2**20 / weight[flow])`` and the
    rank is the new finish tag.  Successful service raises ``V`` to the served
    rank; drops, cancellation and idle visits never do.  A weight update
    affects future attempts only.
    """

    kind = 'wfq'
    __slots__ = ('flowid2weight', 'virtual_time', 'flowid2finish')

    def __init__(self, flowid2weight, virtual_time=0, flowid2finish=None):
        self.flowid2weight = dict(flowid2weight)
        self.virtual_time = virtual_time
        if flowid2finish is None:
            self.flowid2finish = dict.fromkeys(self.flowid2weight, 0)
        else:
            self.flowid2finish = dict(flowid2finish)

    def rank_cal(self, pkt: Pkt) -> int:
        try:
            weight = self.flowid2weight[pkt.flowid]
        except KeyError:
            raise ValueError('undeclared wfq flow') from None
        finish = self.flowid2finish[pkt.flowid]
        virtual = self.virtual_time
        if finish < virtual:
            finish = virtual
        length = pkt.length
        finish += (length * QUANTUM + weight - 1) // weight
        self.flowid2finish[pkt.flowid] = finish
        return finish

    def post_dequeue(self, pkt: Pkt, rank: int):
        if rank > self.virtual_time:
            self.virtual_time = rank

    def set_weight(self, flow, weight):
        if flow not in self.flowid2weight:
            raise ValueError('undeclared wfq flow')
        self.flowid2weight[flow] = weight

    def snapshot(self):
        return ('wfq', self.virtual_time, dict(self.flowid2weight),
                dict(self.flowid2finish))

    def restore(self, state):
        self.virtual_time = state[1]
        self.flowid2weight = dict(state[2])
        self.flowid2finish = dict(state[3])

    def certificate(self):
        weights = self.flowid2weight
        finish = self.flowid2finish
        flows = sorted(weights)
        return {'kind': 'wfq', 'virtual_time': self.virtual_time,
                'weights': [[flow, weights[flow]] for flow in flows],
                'finish': [[flow, finish[flow]] for flow in flows]}
