"""Extended experiment entry: run a complete branchable batch.

``run_request`` validates one JSON batch, replays every run's command array
against :class:`scheduler.StagedPIFOScheduler` and returns the event log plus
the final state certificate for the active branch of each run.
"""
from packet import Pkt
from algorithms import (FifoAlgorithm, SpAlgorithm, WFQAlgorithm,
                        pFabricAlgorithm)
from scheduler import StagedPIFOScheduler
from validate import validate_request


def build_policy(spec):
    kind = spec[0]
    if kind == 'fifo':
        return FifoAlgorithm()
    if kind == 'sp':
        return SpAlgorithm(spec[1])
    if kind == 'sff':
        return pFabricAlgorithm()
    if kind == 'wfq':
        return WFQAlgorithm(spec[1])
    raise ValueError('unknown policy kind')


def execute_run(cfg):
    """Replay one run and return ``{"log": [...], "state": {...}}``."""
    policy = build_policy(cfg['policy'])
    sch = StagedPIFOScheduler(policy, cfg['banks'], cfg['load_balancers'],
                              cfg['fifo_bytes'], cfg['pifo_bytes'],
                              cfg['refill_batch'], cfg['sample_period'],
                              cfg['borders'])
    period = cfg['sample_period']
    log = []
    append = log.append
    saves = {}

    for index, command in enumerate(cfg['events']):
        head = command[0]
        if head == 'enqueue':
            _, pktid, flow, length, size = command
            pkt = Pkt(pktid, flow, length, size)
            rank, l, r, q, accepted = sch.enqueue(pkt, index)
            append([index, 'enqueue', pktid, rank, l, r, q, accepted])
            if accepted and sch.a == period:
                captured, history = sch.sample()
                append([index, 'sample', captured, history])
        elif head == 'dequeue':
            for _ in range(command[1]):
                tick, q, pktid, rank, error, lag, evicted = sch.service()
                append([index, 'dequeue', tick, q, pktid, rank, error, lag,
                        evicted])
        elif head == 'sample':
            captured, history = sch.sample()
            append([index, 'sample', captured, history])
        elif head == 'repartition':
            append([index, 'repartition', sch.repartition(command[1])])
        elif head == 'cancel':
            stage, bank, lag = sch.cancel(command[1])
            append([index, 'cancel', command[1], stage, bank, lag])
        elif head == 'inspect':
            append([index, 'inspect', command[1], sch.inspect(command[1])])
        elif head == 'weight':
            policy.set_weight(command[1], command[2])
            append([index, 'weight', command[1], command[2]])
        elif head == 'save':
            saves[command[1]] = sch.checkpoint()
            append([index, 'save', command[1]])
        else:  # restore
            name = command[1]
            snapshot = saves.get(name)
            if snapshot is None:
                raise ValueError('restore names a slot that was never saved')
            sch.restore(snapshot)
            append([index, 'restore', name])

    return {'log': log, 'state': sch.certificate()}


def run_request(request):
    """Execute a complete batch; returns the response object."""
    return {'runs': [execute_run(cfg) for cfg in validate_request(request)]}
