"""Worst-case-scale timing: build requests at the published bounds."""
import json
import random
import subprocess
import sys
import time


def gen_big_backlog(seed=1):
    rng = random.Random(seed)
    U = 10 ** 9
    borders = [0] + sorted(rng.sample(range(1, U), 63)) + [U]
    events = []
    pid = 0
    for i in range(60000):
        events.append(['enqueue', pid, rng.randint(0, 50), rng.randint(1, 1000), rng.randint(0, U)])
        pid += 1
        if i % 300 == 299:
            events.append(['sample'])
        if i % 5000 == 4999:
            events.append(['save', i // 5000])
        if i % 5000 == 4000:
            events.append(['restore', (i // 5000) - 1])
    left = 40000
    while left:
        n = min(left, rng.randint(1, 50))
        events.append(['dequeue', n])
        left -= n
        if left % 5000 < 50:
            events.append(['sample'])
    return {'banks': 16, 'load_balancers': 8, 'fifo_bytes': 10 ** 9,
            'pifo_bytes': 10 ** 9, 'refill_batch': 32, 'sample_period': 100000,
            'borders': borders, 'policy': {'kind': 'sff'}, 'events': events}


def gen_branchy(seed=2):
    runs = []
    rng = random.Random(seed)
    for k in range(8):
        U = 10 ** 6
        borders = [0] + sorted(rng.sample(range(1, U), 15)) + [U]
        events = []
        pid = k * 10 ** 5
        saves = []
        for i in range(12000):
            events.append(['enqueue', pid, pid % 7, rng.randint(1, 500), rng.randint(0, U)])
            pid += 1
            if i % 200 == 199:
                name = i // 200 % 64
                events.append(['save', name])
                saves.append(name)
            if i % 200 == 100 and saves:
                events.append(['restore', rng.choice(saves)])
            if i % 3 == 0:
                events.append(['dequeue', 1])
        runs.append({'banks': 4, 'load_balancers': 2, 'fifo_bytes': 10 ** 7,
                     'pifo_bytes': 10 ** 7, 'refill_batch': 8,
                     'sample_period': 100000, 'borders': borders,
                     'policy': {'kind': 'fifo'}, 'events': events})
    return {'runs': runs}


def gen_repartition(seed=3):
    rng = random.Random(seed)
    U = 10 ** 6
    events = []
    pid = 0
    for i in range(30000):
        events.append(['enqueue', pid, 1, rng.randint(1, 100), rng.randint(0, U)])
        pid += 1
        if i % 40 == 39:
            borders = [0] + sorted(rng.sample(range(1, U), rng.randint(1, 63))) + [U]
            events.append(['repartition', borders])
    events.append(['dequeue', 20000])
    return {'banks': 2, 'load_balancers': 1, 'fifo_bytes': 10 ** 9,
            'pifo_bytes': 10 ** 9, 'refill_batch': 16, 'sample_period': 97,
            'borders': [0] + sorted(rng.sample(range(1, U), 63)) + [U],
            'policy': {'kind': 'wfq', 'weights': [[1, 7]]}, 'events': events}


def main():
    which = sys.argv[1] if len(sys.argv) > 1 else 'all'
    gens = {'big': gen_big_backlog, 'branchy': gen_branchy, 'repart': gen_repartition}
    for name, gen in gens.items():
        if which not in ('all', name):
            continue
        payload = gen()
        if 'runs' not in payload:
            payload = {'runs': [payload]}
        data = json.dumps(payload).encode()
        start = time.monotonic()
        proc = subprocess.run([sys.executable, '-I', '-B', '/workspace/submission/cli.py'],
                              input=data, capture_output=True, cwd='/workspace')
        wall = time.monotonic() - start
        out = proc.stdout
        ok = proc.returncode == 0 and out[:1] == b'{'
        rows = 0
        if ok:
            try:
                parsed = json.loads(out)
                rows = sum(len(r['log']) for r in parsed.get('runs', []))
            except Exception:
                ok = False
        print('%-8s input=%7d KiB output=%7d KiB rows=%6d wall=%6.2fs rc=%d ok=%s'
              % (name, len(data) // 1024, len(out) // 1024, rows, wall, proc.returncode, ok))
        if not ok:
            print('  stderr:', proc.stderr[:400])
            print('  stdout head:', out[:200])


if __name__ == '__main__':
    main()
