# Alias used by the experiment adapter.
SffAlgorithm = pFabricAlgorithm


class WFQAlgorithm(SchedulingAlgorithm):
    """Quantized weighted fair queueing finish tags, exact integer arithmetic.

    ``F[flow] = max(F[flow], V) + ceil(length * 2**20 / weight[flow])`` and the
    rank is the new finish tag.  Successful service raises ``V`` to the served
    rank; drops, cancellation and idle visits never do.  A weight update
    affects future attempts only.
    """

    kind = 'wfq'
    __slots__ = ('flowid2weight', 'virtual_time', 'flowid2finish', '_shared')

    def __init__(self, flowid2weight, virtual_time=0, flowid2finish=None):
        self.flowid2weight = dict(flowid2weight)
        self.virtual_time = virtual_time
        if flowid2finish is None:
            self.flowid2finish = dict.fromkeys(self.flowid2weight, 0)
        else:
            self.flowid2finish = dict(flowid2finish)
        self._shared = False

    def _detach(self):
        """Copy-on-write: checkpoints share the tables until one mutates."""
        if self._shared:
            self.flowid2weight = dict(self.flowid2weight)
            self.flowid2finish = dict(self.flowid2finish)
            self._shared = False

    def rank_cal(self, pkt: Pkt) -> int:
        try:
            weight = self.flowid2weight[pkt.flowid]
        except KeyError:
            raise ValueError('undeclared wfq flow') from None
        finish = self.flowid2finish[pkt.flowid]
        virtual = self.virtual_time
        if finish < virtual:
            finish = virtual
        length = pkt.length
        finish += (length * QUANTUM + weight - 1) // weight
        self._detach()
        self.flowid2finish[pkt.flowid] = finish
        return finish

    def post_dequeue(self, pkt: Pkt, rank: int):
        if rank > self.virtual_time:
            self.virtual_time = rank

    def set_weight(self, flow, weight):
        if flow not in self.flowid2weight:
            raise ValueError('undeclared wfq flow')
        self._detach()
        self.flowid2weight[flow] = weight

    def snapshot(self):
        self._shared = True
        return ('wfq', self.virtual_time, self.flowid2weight,
                self.flowid2finish)

    def restore(self, state):
        self.virtual_time = state[1]
        self.flowid2weight = state[2]
        self.flowid2finish = state[3]
        self._shared = True

    def certificate(self):
        weights = self.flowid2weight
        finish = self.flowid2finish
        flows = sorted(weights)
        return {'kind': 'wfq', 'virtual_time': self.virtual_time,
                'weights': [[flow, weights[flow]] for flow in flows],
                'finish': [[flow, finish[flow]] for flow in flows]}
